cd /home/user/rork-app && echo "=== CHECK BACKEND INDEPENDENCE STATUS FOR TOOLKIT CREDS ===" && TOKEN=$(cat /tmp/owner_token.txt 2>/dev/null) && curl -sS --max-time 15 "https://api.ivxholding.com/api/ivx/independence-status" -H "Authorization: Bearer $TOKEN" 2>/dev/null > /tmp/indep.json && bun -e "
const d=require('/tmp/indep.json');
if(!d.ok){console.log('error:',d.error);console.log('full:',JSON.stringify(d).slice(0,500));process.exit(0);}
// Look for toolkit URL or rork env vars in the response
const s=JSON.stringify(d);
const toolkitMatch = s.match(/toolkit[^\"]*\"[^\"]*\"/gi);
const rorkUrlMatch = s.match(/(https?:\/\/[^\"\\s]*rork[^\"\\s]*)/gi);
console.log('toolkit matches:', toolkitMatch?.slice(0,5));
console.log('rork URL matches:', rorkUrlMatch?.slice(0,5));
// Check dependencies section
if(d.dependencies){
  for(const dep of d.dependencies){
    if(/toolkit|rork.*env|EXPO_PUBLIC_RORK/i.test(dep.dependency || '')){
      console.log('DEP:', dep.dependency, '→ present:', dep.present);
    }
  }
}
// Check rorkDeps
if(d.rorkDeps){
  for(const dep of d.rorkDeps){
    if(/toolkit|env/i.test(dep.dependency || '')){
      console.log('RORKDEP:', dep.dependency, '→ present:', dep.present, 'detail:', dep.detail);
    }
  }
}
" 2>&1

